# -*- coding: utf-8 -*-
"""Stage 3 merge for research document 'Quit Habit Decision.md'."""
import json
P = "Tools/prd_ledger/canonical.json"
L = json.load(open(P)); C = {x["id"]: x for x in L}
def ext(cid, text):
    if text not in C[cid]["statement"]: C[cid]["statement"] += text
def add(cid, section, title, statement):
    if cid in C: return
    e = dict(id=cid, title=title, statement=statement, section=section, cards=[], reports=[], merged_from=[])
    C[cid] = e; L.append(e)

add("C309", "dont", "Quit tracking belongs inside the habit app as a habit type — never as a second, generic 'quit anything' app",
    "Research: Quit Habit Decision.md (evidence base: 56,653 reviews of the category's #1 app, 10,621 reviews of the leading quit tracker, App Store ratings counts). The generic quit market is one incumbent and a graveyard — Days Since 19,073 US ratings, Quitzilla 1,473, Quit Bad Habits & Addiction 1,061, Days Without 6, ZeroBadHabits 0 — so a generic quit app's ceiling is roughly 19k US ratings. The money is in verticals, which beat every generic quit app by 3-10x: I Am Sober 186,328, Smoke Free 57,263, Reframe: Drink Less 44,339, Sober Time 41,632, Nomo 16,398, QuitNow! 13,572; someone quitting smoking searches 'quit smoking', not 'quit tracker', and wants lung-recovery milestones, craving support and a community that a generic counter does not provide. A generic quit app therefore loses on both sides: 'too vague for the vertical searcher, and redundant for the habit-tracker user.' The audiences barely migrate — only 2.4% of Days Since reviewers ask for good-habit building — which removes the cannibalisation risk and the cross-sell case at once: 'Two apps, two ASO efforts, two support queues, for two groups that don't migrate.' Three costs are named for the second listing: it competes with your own app for the same keywords, caps out around 19k ratings, and reads as a repackage. The upside of keeping it in one listing is a keyword surface: Days Since ranks #3 overall in the category on ranking strength and #1 in 10 rich markets purely on quit terms, so a proper quit mode lets one listing compete for 'quit habit', 'break bad habits' and 'sobriety tracker' alongside the habit keywords 'without splitting your ASO across two listings'. If a second app is ever built it must be vertical and genuinely different — the named opening is phone/social-media quitting, 2.0% of Days Since reviews and the third-biggest quit reason with no large dedicated app owning it — and the bar is content, not skin: 'That is a different product with different content, not a reskin, so it wouldn't look like spam.' Related: [[C019]] (the quit-habit mode itself), [[C060]] (cross-selling an app family), [[C278]] (a name that collides with a competitor), [[C140]] (marketing the generic-tracker use case).")

add("C310", "product-rule", "A low request count for a feature the market leader already ships measures satisfaction with that implementation, not demand for the feature",
    "Research: Quit Habit Decision.md. Of 56,653 reviews of the category's #1 app only 164 (0.29%) mention quitting — a count that reads as no demand until the reviews are read, at which point they are 'overwhelmingly complaints about the existing quit feature, not requests for one': 'the streak counter is sometimes wrong for Quit habits'; 'It is not possible to track if you want to quit drinking alcohol. You can only choose a max period of 1 month with a 2 drink minimum?'; \"When habits are set to 'Quit' with 0 per day - nothing is readable because of the all dark colors\"; 'I click the QUIT habit tab, I get the form error'; 'Bad for quitting habits'. The rule generalises to every request count in every report in this ledger: a request code is generated by absence, so a feature that already exists produces complaint codes instead, and the two must never be compared as if they measured the same thing. Its corollary is the opportunity statement: 'The leader ships quit-habits badly. Doing it properly is a differentiator inside your existing app - and costs you nothing in downloads, because the traffic is already coming for habit tracking.' Related: [[C019]], [[C309]], [[C142]] (users not finding features that already exist).")

ext("C019", " Research: Quit Habit Decision.md — the decision memo for this point, and it settles three things. (1) Quit is parity, not differentiation: 8 of the top 40 habit trackers explicitly market breaking bad habits, including Habit Tracker (#1), HabitKit, Streaks and Simple Streak, and the #1 app already ships a Quit tab — 'Shipping it doesn't differentiate you. Not shipping it is starting to look like a gap.' (2) The differentiation is in the implementation, because the leader's is defective in five named ways (wrong streak count on quit habits; an alcohol ceiling of a one-month maximum period with a two-drink minimum; unreadable dark colours when the target is 0 per day; a form error on the Quit tab; 'Bad for quitting habits') — see [[C310]]. (3) The build spec, five items: a days-since counter rather than a streak ('Quitting is days clean, not did it today'); a relapse that does not wipe history — the most-repeated complaint across the 10,621-review Days Since corpus — logging the slip, keeping the record and showing best-ever beside current ([[C308]], [[C216]]); allowances rather than only zero, because '2 drinks a week' is a real goal and the leader's one-month cap draws loud complaints ([[C048]], [[C108]]); milestones with meaning at 1/7/30/90 days plus money saved, which is where the leading quit corpus is happiest — milestone-screenshot reviews average 4.77★ ([[C101]], [[C100]]); and readable in dark mode ([[C080]], [[C171]]). What people actually quit, from 10,621 Days Since reviews: alcohol 5.0%, smoking/vaping 3.7%, social media/phone 2.0%, sugar/junk food 1.0%, weed/drugs 0.7%, nail biting/caffeine/gambling 0.6%, porn 0.2% — the top two are locked up by the verticals and phone/social-media use is the one quit niche with genuine room. Ship it as a habit type in this app, not as a second listing ([[C309]]).")
ext("C308", " Research: Quit Habit Decision.md — 'a relapse must not wipe history' is named as the single most-repeated complaint in the 10,621-review corpus of the leading quit tracker, i.e. the defining failure mode of the whole quit category, and the specified behaviour is to log the slip, keep the record and show best-ever alongside current.")
ext("C216", " Research: Quit Habit Decision.md — for quit habits the forgiving measure is 'best-ever vs current' shown together, so a relapse costs the current number without erasing the achievement; a relapse that wipes history is the most-repeated complaint across 10,621 reviews of the leading quit tracker.")
ext("C101", " Research: Quit Habit Decision.md — in the leading quit tracker's 10,621-review corpus the happiest reviews (4.77★ average) are milestone screenshots, which makes the milestone screen simultaneously the retention moment and the organic-sharing surface; specified milestones are 1/7/30/90 days plus money saved.")
ext("C100", " Research: Quit Habit Decision.md — money saved is specified as part of the quit milestone set (1/7/30/90 days plus money saved), where the milestone screen is the best-rated moment in the leading quit corpus (4.77★).")
ext("C048", " Research: Quit Habit Decision.md — quit habits need allowances, not only zero: \"'2 drinks a week' is a real goal\", and the #1 app's ceiling (a maximum period of one month with a two-drink minimum) draws loud complaints; moderation is a distinct tracking mode from abstinence.")
ext("C108", " Research: Quit Habit Decision.md — a quit goal is an allowance ('2 drinks a week'), not only a zero target, and the leader's one-month maximum period is quoted as a blocking limitation for alcohol tracking.")
ext("C080", " Research: Quit Habit Decision.md — a literal, fixable contrast defect in the #1 app: quit habits set to 0 per day render as 'nothing is readable because of the all dark colors', so the zero-target state needs its own dark-mode check.")
ext("C171", " Research: Quit Habit Decision.md — the #1 app's quit habits at a 0/day target are unreadable in dark mode, a contrast failure that appears only in that state and would be missed by a check of the default states.")
ext("C060", " Research: Quit Habit Decision.md — the limit of the app-family play: a second, generic quit app gains almost no cross-sell because the audiences do not migrate (only 2.4% of quit-tracker reviewers ask for good-habit building), while costing two ASO efforts and two support queues; a second listing is only worth it when it is a genuinely different vertical product ([[C309]]).")
ext("C278", " Research: Quit Habit Decision.md — the same reasoning applied to your own catalogue: a generic quit app shipped beside your habit app 'would compete with your own app for the same keywords… and read as a repackage'; a second listing has to be a different product with different content 'so it wouldn't look like spam'.")
ext("C140", " Research: Quit Habit Decision.md — quit terms are a keyword surface one listing can annex: Days Since ranks #3 overall in the category on ranking strength and #1 in 10 rich markets purely on quit terms, so shipping a proper quit mode lets a single listing compete for 'quit habit', 'break bad habits' and 'sobriety tracker' alongside the habit keywords.")
ext("C142", " Research: Quit Habit Decision.md — the inverse-reading rule: when the leader already ships a feature, its request count collapses and is replaced by complaint codes (164 of 56,653 reviews, 0.29%, almost all complaints), so a low count must never be read as low demand ([[C310]]).")

MAP = {
 "RQH-001": [], "RQH-002": ["C309", "C019"], "RQH-003": ["C309", "C019"], "RQH-004": ["C019"],
 "RQH-005": ["C310", "C142"], "RQH-006": ["C310", "C019", "C308"], "RQH-007": ["C309", "C060"],
 "RQH-008": ["C019", "C309"], "RQH-009": ["C019"], "RQH-010": ["C308", "C019", "C216"],
 "RQH-011": ["C019", "C048", "C108"], "RQH-012": ["C101", "C100", "C019"],
 "RQH-013": ["C080", "C171", "C019"], "RQH-014": ["C309", "C278"], "RQH-015": ["C309", "C060"],
 "RQH-016": ["C309", "C140"],
}
path = "Tools/prd_ledger/research_quit_habit/cards.jsonl"
cards = [json.loads(l) for l in open(path) if l.strip()]
for c in cards:
    c["canonical"] = MAP[c["id"]]
    for cid in MAP[c["id"]]:
        if c["id"] not in C[cid]["cards"]: C[cid]["cards"].append(c["id"])
        if c["report"] not in C[cid]["reports"]: C[cid]["reports"].append(c["report"])
with open(path, "w") as f:
    for c in cards: f.write(json.dumps(c, ensure_ascii=False) + "\n")
json.dump(L, open(P, "w"), ensure_ascii=False, indent=1)
print("merged", len(cards), "cards;", sum(1 for c in cards if not c["canonical"]), "left in nuance register; canonical now", len(L))
